#!/usr/bin/env bash
# check_file_size_selftest.sh: self-test for .githooks/check_file_size.sh
# (the 1000-line file-size ratchet, task #924).
#
# Guard cases build throwaway git repos under the system temp directory
# and run the real guard inside them, asserting:
#   1. a 1001-line .go file fails;
#   2. the same file with a "Code generated ... DO NOT EDIT." header
#      passes (content-based generated detection);
#   3. an allowlisted file that grew by one line fails (the ratchet;
#      at its recorded count it still passes);
#   4. an allowlisted file now at <= 1000 lines fails with the "remove
#      it from the allowlist" message (the list must shrink);
#   5. a clean tree, including a file at exactly 1000 lines, passes.
#
# Cross-check against the REAL repository: the allowlist has a second
# enforcement layer, .golangci.yml's revive file-length-limit rule, with
# one exclusion per allowlisted .go file, tagged "# file-size-ratchet"
# on the path line. The allowlist is the single source of truth and the
# yml exclusions are derived from it; this test asserts the bijection in
# BOTH directions (every allowlisted .go file has a tagged entry, every
# tagged entry is allowlisted), so drift on either side fails pre-push.
# revive only lints Go, so filtering the allowlist to .go paths is
# correct, not a gap (web/src/store.ts lives in the allowlist only).
#
# mktemp -d is deliberately NOT used: this repository's Windows shells
# hand out a virtual /tmp path that child processes cannot resolve, so
# the temp root is built from the standard environment variables, and
# every path below is used in ways (shell redirects, git -C, awk file
# arguments) that survive Windows-style separators. No Windows path is
# ever passed through `awk -v`, whose values undergo backslash-escape
# processing.
set -uo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
guard="$script_dir/check_file_size.sh"
allowlist_file="$script_dir/file_size_allowlist.txt"
golangci_yml="$script_dir/../.golangci.yml"

for required in "$guard" "$allowlist_file" "$golangci_yml"; do
	if [ ! -f "$required" ]; then
		printf 'check_file_size_selftest.sh: cannot find %s\n' "$required" >&2
		exit 1
	fi
done

tmp_base="${TMPDIR:-${TEMP:-${TMP:-/tmp}}}/check_file_size_selftest.$$"
if ! mkdir -p "$tmp_base"; then
	printf 'check_file_size_selftest.sh: cannot create %s\n' "$tmp_base" >&2
	exit 1
fi
cleanup() {
	rm -rf -- "$tmp_base" || :
}
trap cleanup EXIT

failures=0

expect_status() {
	desc="$1"
	want="$2"
	got="$3"
	if [ "$got" -eq "$want" ]; then
		printf 'PASS: %s (exit %s)\n' "$desc" "$got"
	else
		printf 'FAIL: %s -- expected exit %s, got %s\n' "$desc" "$want" "$got"
		failures=$((failures + 1))
	fi
}

expect_output_contains() {
	desc="$1"
	got="$2"
	want="$3"
	case "$got" in
	*"$want"*)
		printf 'PASS: %s\n' "$desc"
		;;
	*)
		printf 'FAIL: %s -- output does not contain [%s]\n' "$desc" "$want"
		failures=$((failures + 1))
		;;
	esac
}

# new_repo <n>: fresh throwaway git repo with an empty allowlist; its
# path on stdout, or empty on failure.
new_repo() {
	repo="$tmp_base/repo$1"
	rm -rf -- "$repo" || return 1
	if ! mkdir -p "$repo/.githooks"; then
		return 1
	fi
	if ! : >"$repo/.githooks/file_size_allowlist.txt"; then
		return 1
	fi
	if ! git -C "$repo" init -q >/dev/null 2>&1; then
		return 1
	fi
	printf '%s' "$repo"
}

# write_filler <path> <lines> [first-line]: a file with exactly <lines>
# lines, optionally starting with a marker line. The path is a shell
# redirect target only -- never an awk -v value (escape processing).
write_filler() {
	awk -v lines="$2" -v first="${3:-}" 'BEGIN {
		if (first != "") {
			print first
			lines--
		}
		for (i = 1; i <= lines; i++) {
			print "filler line " i
		}
	}' >"$1"
}

# run_guard <repo>: runs the guard inside <repo>; leaves combined output
# in $out and the exit status in $status.
run_guard() {
	out="$(cd "$1" && bash "$guard" 2>&1)"
	status=$?
}

# Case 1 (and 2): an unallowlisted 1001-line .go file fails; the same
# file with a generated marker on line 1 passes.
repo="$(new_repo 1)"
if [ -z "$repo" ]; then
	printf 'FAIL: case 1: could not create the throwaway repo\n'
	failures=$((failures + 1))
else
	write_filler "$repo/big.go" 1001
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 1: a 1001-line .go file fails" 1 "$status"
	expect_output_contains "case 1: names the file and its count" "$out" "TOO LONG: big.go is 1001 lines"

	write_filler "$repo/big.go" 1001 "// Code generated by tool. DO NOT EDIT."
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 2: the same file with a generated-marker header passes" 0 "$status"
	expect_output_contains "case 2: reports the file as generated" "$out" "1 generated skipped"
fi

# Case 3: the ratchet -- an allowlisted file that grows by one line
# fails; at its recorded count it passes.
repo="$(new_repo 3)"
if [ -z "$repo" ]; then
	printf 'FAIL: case 3: could not create the throwaway repo\n'
	failures=$((failures + 1))
else
	write_filler "$repo/big.go" 1100
	printf 'big.go 1100\n' >"$repo/.githooks/file_size_allowlist.txt"
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 3: allowlisted file at its recorded count passes" 0 "$status"

	printf 'filler line extra\n' >>"$repo/big.go"
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 3: allowlisted file grown by one line fails" 1 "$status"
	expect_output_contains "case 3: reports the growth against the recorded count" "$out" "RATCHET VIOLATION: big.go grew to 1101 lines (allowlist records 1100)"
fi

# Case 4: a file fixed down to <= 1000 must be removed from the
# allowlist; keeping the line would silently turn the ratchet into an
# exemption list.
repo="$(new_repo 4)"
if [ -z "$repo" ]; then
	printf 'FAIL: case 4: could not create the throwaway repo\n'
	failures=$((failures + 1))
else
	write_filler "$repo/big.go" 1100
	printf 'big.go 1100\n' >"$repo/.githooks/file_size_allowlist.txt"
	(cd "$repo" && git add -A >/dev/null 2>&1)
	write_filler "$repo/big.go" 999
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 4: allowlisted file now at 999 lines fails" 1 "$status"
	expect_output_contains "case 4: names the file and its new count" "$out" "RATCHET CLEANUP: big.go is now 999 lines"
	expect_output_contains "case 4: asks for the allowlist line to be removed" "$out" "remove it from"
fi

# Case 5: a clean tree passes -- including exactly-1000 lines, the
# boundary (only > max fails).
repo="$(new_repo 5)"
if [ -z "$repo" ]; then
	printf 'FAIL: case 5: could not create the throwaway repo\n'
	failures=$((failures + 1))
else
	write_filler "$repo/ok.go" 1000
	(cd "$repo" && git add -A >/dev/null 2>&1)
	run_guard "$repo"
	expect_status "case 5: clean tree with a file at exactly the limit passes" 0 "$status"
	expect_output_contains "case 5: summary reports no violations" "$out" "1 file(s) checked, 0 generated skipped, 0 allowlisted"
fi

# Case 6: the real repository -- the guard passes, the yml carries the
# revive rule, and the allowlist and the .golangci.yml file-length-limit
# exclusions are exact mirrors of each other.
out="$(bash "$guard" 2>&1)"
status=$?
expect_status "case 6: unmocked guard run on the real repository exits 0" 0 "$status"

if grep -q 'name: file-length-limit' "$golangci_yml" && grep -q 'max: 1000' "$golangci_yml"; then
	printf 'PASS: case 6: .golangci.yml carries the revive file-length-limit rule at max 1000\n'
else
	printf 'FAIL: case 6: .golangci.yml is missing the revive file-length-limit rule (or its max is not 1000)\n'
	failures=$((failures + 1))
fi

al_paths="$tmp_base/allowlist_paths.txt"
yml_paths="$tmp_base/yml_paths.txt"
# Allowlist side: the path is everything before the last space; only .go
# entries need a yml twin (revive lints Go only).
while IFS= read -r line || [ -n "$line" ]; do
	line="${line%$'\r'}"
	case "$line" in
	''|'#'*) continue ;;
	esac
	path="${line% *}"
	case "$path" in
	*.go) printf '%s\n' "$path" ;;
	esac
done <"$allowlist_file" | sort >"$al_paths"

# Yml side: only path lines carrying the load-bearing tag. The path is
# single-quoted, anchored ^...$, dots escaped; un-escape both. The
# "- path:" gate matters: the yml's explanatory comment block mentions
# the tag string too and must not be picked up.
awk '
	index($0, "- path:") && index($0, "# file-size-ratchet") {
		p = substr($0, 1, index($0, "#") - 1)
		sub(/ +$/, "", p)
		sub(/^.*path: */, "", p)
		p = substr(p, 2, length(p) - 2)
		sub(/\^/, "", p)
		sub(/\$$/, "", p)
		gsub(/\\/, "", p)
		print p
	}
' "$golangci_yml" | sort >"$yml_paths"

if [ "$(cat "$al_paths")" = "$(cat "$yml_paths")" ]; then
	printf 'PASS: case 6: allowlist <-> .golangci.yml ratchet bijection (%d paths)\n' "$(grep -c '' "$al_paths")"
else
	printf 'FAIL: case 6: the allowlist and the .golangci.yml file-length-limit exclusions disagree.\nAllowlist (.go) paths:\n'
	cat "$al_paths"
	printf '.golangci.yml tagged paths:\n'
	cat "$yml_paths"
	failures=$((failures + 1))
fi

if [ "$failures" -gt 0 ]; then
	printf 'check_file_size_selftest: %d failure(s)\n' "$failures"
	exit 1
fi
printf 'check_file_size_selftest: all cases passed\n'
exit 0
